using Microsoft.Data.SqlClient;

namespace Bancoficticio.Transferencias.Infrastructure;

/// <summary>One connection and its transaction: every adapter of a request (or of a golden case) works
/// inside it, so a rejection undoes all its writes.</summary>
public sealed class Db(SqlConnection connection) : IDisposable
{
    public SqlConnection Connection { get; } = connection;

    public SqlTransaction? Transaction { get; private set; }

    public static Db Open(string connectionString)
    {
        var connection = new SqlConnection(connectionString);
        connection.Open();
        return new Db(connection);
    }

    public void Begin() => Transaction = Connection.BeginTransaction();

    public void Commit()
    {
        Transaction?.Commit();
        Transaction = null;
    }

    public void Rollback()
    {
        Transaction?.Rollback();
        Transaction = null;
    }

    /// <summary>A command on the connection, inside the current transaction if there is one.</summary>
    public SqlCommand Command(string sql)
    {
        var command = Connection.CreateCommand();
        command.CommandText = sql;
        command.Transaction = Transaction;
        return command;
    }

    public void Dispose()
    {
        Transaction?.Dispose();
        Connection.Dispose();
    }
}


