namespace Bancoficticio.Transferencias.Application;

/// <summary>Application service of the use case RealizarTransferencia (legacy program TRANSFERENCIA).</summary>
public sealed class RealizarTransferenciaService(
    CuentaRepository cuentaRepository,
    TransferenciaRepository transferenciaRepository)
{
    public RealizarTransferenciaResponse Execute(RealizarTransferenciaRequest request)
    {
        // Legacy: TextBox.Text is never null (empty string when no text), then Trim().
        string origen = (request.CuentaOrigen ?? string.Empty).Trim();
        string destino = (request.CuentaDestino ?? string.Empty).Trim();
        // Legacy: decimal.Parse(txtMonto.Text) fails when there is no valid number.
        decimal monto = request.Monto
            ?? throw new FormatException("Input string was not in a correct format.");
        // Legacy: DropDownList.SelectedValue is "" when nothing is selected; not trimmed.
        string tipo = request.Tipo ?? string.Empty;

        // RULE-005: before any database access.
        if (origen == destino)
        {
            throw new BusinessError("SAME_ACCOUNT", "-1", "LA CUENTA DESTINO ES LA MISMA");
        }

        // RULE-006: origin account must exist and be active.
        var cuenta = cuentaRepository.FindByNumero(origen);
        if (cuenta is null)
        {
            throw new BusinessError("ORIGIN_ACCOUNT_NOT_FOUND", "-1", "CUENTA ORIGEN NO EXISTE");
        }
        string? estado = cuenta.Estado;
        // Legacy: r.GetDecimal(1) fails on a NULL balance.
        decimal saldo = cuenta.Saldo!.Value;
        if (estado != "A")
        {
            throw new BusinessError("ORIGIN_ACCOUNT_INACTIVE", "-1", "CUENTA ORIGEN INACTIVA");
        }

        // RULE-007: destination account must exist and be active.
        if (cuentaRepository.CountActivas(destino) == 0)
        {
            throw new BusinessError("DESTINATION_ACCOUNT_NOT_FOUND", "-1", "CUENTA DESTINO NO EXISTE");
        }

        // RULE-001, RULE-002, RULE-003: commission.
        decimal comision = Calcular(monto, tipo);

        // RULE-008: balance check.
        if (saldo < monto + comision)
        {
            throw new BusinessError("INSUFFICIENT_BALANCE", "-1", "SALDO INSUFICIENTE");
        }

        // RULE-009: posting.
        cuentaRepository.Debit(origen, monto + comision);
        cuentaRepository.Credit(destino, monto);

        // RULE-010: registration.
        int numero = transferenciaRepository.NextNumero();
        transferenciaRepository.Insert(numero, origen, destino, monto, comision, tipo);

        return new RealizarTransferenciaResponse(numero, comision, "TRANSFERENCIA REALIZADA");
    }

    private static decimal Calcular(decimal monto, string tipo)
    {
        decimal comision = monto <= 1000m
            ? 0.50m
            : Math.Round(monto * 0.001m, 2, MidpointRounding.AwayFromZero);
        if (comision > 5.00m)
        {
            comision = 5.00m;
        }
        if (tipo == "INM")
        {
            comision += 1.00m;
        }
        return comision;
    }
}
